UPDATE companies SET description='Wood World of Texas LLC operates from a single location in Dallas, Texas. The company emphasizes its authenticity as the original Wood World of Texas site, warning against imitation websites.

The company stocks a wide range of woodworking materials and tools, including domestic and imported lumber (knotty alder, European beech, plywood, veneer, natural-edge slabs), finishing products from brands such as Hampshire Sheen, Chestnut, and Jimmy Clewes, and power tools from Metabo, Skil, DeWalt, and Rikon. It also supplies knife-making kits, gun grips and accessories, turning kits, and outdoor tools like hatchets and tomahawks. Value-added services include sanding and the grading of knotty alder for high-end rustic applications in doors, moldings, and cabinets. Hands-on classes in knife making, cutting boards, and charcuterie boards are offered on-site.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Knotty alder grading for high-end rustic appearance", "Sanding services", "Hands-on woodworking classes (knife making, cutting board, charcuterie board)", "Importing and distribution of woodworking tools and supplies", "Custom finishing product specification (Hampshire Sheen, Chestnut, Jimmy Clewes)"], "industries": ["Woodworking", "Cabinet making", "Door manufacturing", "Molding", "Knife making", "Gunsmithing", "Woodturning", "Pen turning", "Game call making", "Outdoor sporting goods"], "materials": ["Knotty alder", "European beech", "Plywood", "Veneer", "Natural edge slabs", "Rosewood", "Bone", "Hickory", "1055HC steel", "1060HC steel", "1065 carbon steel"], "equipment": [], "volume": "", "lead_time": "7-14 days for certain stocked items", "tolerances": "", "built_on": [], "facts_used": ["Location: Dallas, Texas -> db", "Single location, authentic site -> /", "Contact: Craig C (Craig Fyock) -> /", "Products: lumber, plywood, veneer, slabs, finishing products, tools, knife making supplies, gun grips -> /", "Services: sanding, knotty alder grading, hands-on classes -> / and db", "Brands carried: Hampshire Sheen, Chestnut, Jimmy Clewes, Thompson Turning Tools, Metabo, Skil, DeWalt, Rikon, Hock -> /", "Imports hard-to-find product lines -> / (blog)", "