UPDATE companies SET description='Wooden Hammer was founded in 2009 by Ben Raphael in Monkton, Vermont. After graduating cum laude from Colby College and apprenticing with two skilled carpenters, Raphael established the shop in the Champlain Valley with a focus on custom woodwork and carpentry. The business remains intentionally small, operated by Raphael and an assistant, allowing direct communication with the craftsman from initial contact through project completion.

The company produces custom cabinetry, fine furniture, and built-in woodwork for residential spaces, including kitchen cabinets, bathroom vanities, and custom tables. All work is performed in a small-scale woodshop that prioritizes detail over volume, with no assembly-line production. The shop works with Vermont-sourced wood products as well as building materials sourced nationally, depending on client preference.

Testimonials reference clients in Burlington, South Burlington, and Manhattan, New York, indicating a reach beyond the local area. Projects range from kitchen and bathroom renovations to standalone furniture pieces.

Raphael founded the company to avoid the impersonal nature of bulk distribution and assembly-line construction, emphasizing sustainability and personal service. The shop''s differentiators include a sustainability-minded material approach, direct craftsman-to-client communication, and a deliberate choice to remain small to maintain quality control on every piece.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinetry", "Fine furniture making", "Built-in woodwork", "Kitchen cabinet fabrication", "Bathroom vanity fabrication", "Custom table making", "Carpentry", "Woodworking"], "industries": ["Homeowners", "Builders", "Designers", "Architects"], "materials": ["Vermont wood products", "Building materials from various sources"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Small shop by design for personalized care and detail", "Direct communication with the craftsman throughout the project", "Sustainability-minded using Vermont wood products", "Custom cabinetry, furniture, and built-ins for residential projects"], "facts_used": ["Founded in 2009 by Ben Raphael -> /about-us", "Shop located in Monkton, Vermont -> /", "Small shop operated by Ben Raphael and an assistant -> /about-us", "Custom cabinetry, fine furniture, built-ins, kitchen cabinets, bathroom vanities, custom tables -> /", "Serves homeowners, builders, designers, architects -> /", "Uses Vermont wood products and building materials from far and wide -> /", "Direct communication with craftsman from first contact to completion -> /about-us", "Sustainability focus -> /", "Headquarters in North Ferrisburgh, Vermont -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "we craft high-quality custom cabinetry and woodwork", "founded_year": "2009", "employee_count": "2", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wooden-hammer' AND approved AND profile IS NULL;
UPDATE companies SET description='The business began when its founder, a hobby woodworker and engineer by trade, built a timber frame workshop and decided to saw his own lumber to save money and apply his knowledge of wood. Seeing usable logs turned into firewood or left to rot, he started sawing for others to put that resource to work.

The company provides plane (dimensional) sawing for construction-grade lumber and grade sawing to maximize high-quality, knot-free boards. It also sharpens and sets band saw blades using a Wood Mizer CBN profile sharpener and a Woodmizer Dual Tooth Setter, and sharpens chainsaw chains with an Oregon 520-120 grinder. In addition, it offers woodworking 3D modeling from concept evaluation through CNC routing.

Customers range from weekend warriors to serious enthusiasts who need custom sawn lumber for personal projects. The service area covers hobbyists and small-scale builders across western Wisconsin who bring their own logs for processing.

The goal is to save clients time and money not only at the sawmill but throughout their subsequent projects.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Plane (Dimensional) Sawing", "Grade Sawing", "Band Saw Blade Sharpening and Setting", "Chainsaw Chain Sharpening", "Woodworking 3D Modeling", "CNC Routing"], "industries": ["Woodworking", "Construction lumber", "Hobbyist woodworking"], "materials": [], "equipment": ["Wood Mizer CBN profile sharpener", "Woodmizer Dual Tooth Setter", "Oregon 520-120"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Mobile custom sawing within 100+ miles of Menomonie, WI", "Engineer''s detail-oriented approach to maximize lumber value", "Band saw blade sharpening with Wood Mizer CBN profile sharpener and Dual Tooth Setter", "Chainsaw chain sharpening with Oregon 520-120", "Woodworking 3D modeling from concept to CNC routing"], "facts_used": ["Company name and location from db", "Service area and custom sawing description from /", "Founder background and motivation from /about-us", "Services and equipment from /services", "Customer types from / and /about-us", "Differentiators from /about-us and /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Providing custom sawing within 100+ miles of Menomonie, WI.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='woods-to-workshop-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='The shop produces one-of-a-kind pieces including dining tables, benches, live-edge countertops, shelves, and specialty items such as shot-glass displays. The workshop has no showroom; clients collaborate directly on design before fabrication begins.

The clientele is primarily residential—homeowners and rental-property owners seeking bespoke furniture for dining rooms, bourbon rooms, and custom millwork. Testimonials reference projects for private homes and a rental house on Hilton Head Island.

