UPDATE companies SET description='Workwear Outfitters is headquartered in Nashville, Tennessee. The company operates as a manufacturer of innovative work apparel and footwear, with facilities spanning the globe. While its founding year and ownership structure are not publicly disclosed, the business has grown into a large-scale producer serving a worldwide workforce.

The company produces a range of workwear products, including apparel and footwear, serving millions of workers across industrial, service, and government sectors. Its global footprint encompasses multiple facilities and a workforce of more than 5,800 employees. Specific manufacturing processes, production volumes, and part numbers are not detailed in available sources.

Workwear Outfitters supplies industrial, service, and governmental workers, providing protective and functional clothing for diverse job environments. Its customer base includes organizations that outfit employees in demanding conditions, from construction sites to public service agencies. The company also offers a virtual sizing tool called Workfitter to assist with fit selection.

The company positions itself as a global authority in workwear, emphasizing innovation and protection for workers. It has developed tools such as Workfitter, a virtual sizing technology, to improve the buying experience and maintains a portfolio of brands that includes Red Kap and OOBE. These elements reflect its stated focus on the market through product development and worker-centric solutions.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Work apparel manufacturing", "Footwear manufacturing", "Virtual sizing technology (Workfitter)"], "industries": ["Industrial", "Service", "Government"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Virtual sizing tool (Workfitter) for improved buying experience", "Global manufacturing footprint with over 5,800 employees", "Portfolio of brands including Red Kap and OOBE", "Focus on industrial, service, and government worker segments"], "facts_used": ["Headquartered in Nashville, Tennessee -> db", "Employs more than 5,800 people -> db", "Manufacturer of innovative work apparel and footwear -> db", "Serves industrial, service, and governmental workers -> /", "Offers virtual sizing tool Workfitter -> /", "Brands include Red Kap and OOBE -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "leading manufacturer of innovative work apparel and footwear", "founded_year": "", "employee_count": "5,800+", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='workwear-outfitters' AND approved AND profile IS NULL;
UPDATE companies SET description='World Class Woodworking operates from Gilbert, Arizona. The company was founded by Frank D’Esposito, whose emphasis on detail, moral values, and a vision for employee success has shaped its reputation.

The shop produces custom wood products including cabinetry for kitchens, bars, baths, and furniture. It manufactures all of its wood door styles in-house, offers finish matching for any color, and uses a CAD shop drawing process to visualize projects before fabrication. Services span cabinet refacing, refinishing, full replacement, and new builds for both residential and commercial spaces, with installation performed by the same team.

Cabinet refacing is highlighted as a fast-growing segment of the remodeling industry, allowing clients to refresh existing layouts without full demolition. Projects range from single-door repairs to complete kitchen transformations.

World Class Woodworking differentiates itself through hand-picked material suppliers—such as Decospan’s finest oak collection—and a commitment that no job is too small or too large. The founder’s stated focus on employee success and supplier relationships underpins its approach to quality and service.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinetry (kitchens, bars, baths)", "Custom furniture", "Cabinet refacing", "Cabinet refinishing", "Cabinet replacement and new builds", "CAD shop drawings", "Finish matching", "Wood door manufacturing", "Installation services"], "industries": ["Residential", "Commercial", "Hospitality", "Furniture", "Remodeling"], "materials": ["Wood", "Oak (Decospan finest oak collection)", "Various finishes"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Manufactures all wood door styles in-house", "Matches any finish imaginable", "CAD shop drawing process for pre-visualization", "Hand-picked material suppliers (e.g., Decospan finest oak)", "No job too small or too large"], "facts_used": ["Founder Frank D''Esposito -> db", "Location Gilbert, Arizona -> db", "Manufactures wood door styles -> /", "Offers cabinet refacing, refinishing, replacement -> /services", "CAD shop drawing process -> /services", "Hand-picked material suppliers -> /about", "Decospan finest oak collection -> /about", "No job too small or too big -> /about", "Residential & commercial custom cabinetry -> /", "Installation services -> /", "Custom furniture -> /", "Finish matching -> /", "Serves homeowners and commercial clients -> /services", "Remodeling industry reference -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We manufacture all of our wood door styles", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='world-class-woodworking' AND approved AND profile IS NULL;
UPDATE companies SET description='World Finer Foods is headquartered in Bloomfield, New Jersey. The company traces its roots to 1947 when German immigrant Max H. Ries founded Reese Finer Foods after arriving in the United States in 1939. Originally intending to establish a textile business, Ries pivoted to food importing and built the Reese brand into a specialty-food label.

Today the firm manages and markets more than 60 premium food, beverage and personal-care brands encompassing over 1,000 products. It operates as a full-service distributor and brand manager, providing sales representation, trade and consumer marketing, finance processing (order management, invoicing, promotional spend, deductions and collections) and end-to-end logistics including EDI, FDA compliance, inventory control and warehousing on an Oracle ERP platform. The company serves as the exclusive U.S. customer for its brand partners, selling to more than 350 retail and distribution accounts.

Its client base includes domestic and international specialty-food producers such as Barry’s Tea, Marmite, Bonne Maman, Dr. Woods and London Pub, as well as its own heritage Reese line.

The business was built on the principle that a collective network of producers, importers and distributors could grow together. That relationship-driven philosophy remains central, underscored by membership in the Specialty Food Association, The Food Institute and status as the only U.S. member of the Circle of European Specialty Food Distributors (CEISA).', certifications=ARRAY[]::text[], profile='{"capabilities": ["Brand management", "Distribution", "Sales representation", "Trade marketing", "Consumer marketing", "Finance processing (order management, invoicing, promotional spend, deductions, collections)", "Logistics management (EDI, FDA compliance, inventory control, warehousing)", "Importing", "Market entry strategy", "E-commerce channel management", "Category management", "Retail account management"], "industries": ["Specialty food", "Beverage", "Personal care", "Grocery", "Retail", "E-commerce"], "materials": ["Finished food products", "Beverages", "Personal care items"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Only U.S. member of the Circle of European Specialty Food Distributors (CEISA)", "Exclusive U.S. customer selling brand partners\u2019 products to over 350 retail and distribution accounts", "End-to-end logistics with EDI, FDA compliance, inventory control and warehousing on Oracle ERP", "Long-standing relationships across conventional grocery, specialty retail and e-commerce channels", "Comprehensive sales, marketing and finance services handled in-house"], "facts_used": ["Headquarters: Bloomfield, New Jersey -> db", "Founded 1947 by Max H. Ries -> /about-us", "German immigrant, arrived 1939, textile background -> /about-us", "Reese brand leading specialty foods -> /about-us", "Manages 60+ brands, 1000+ products -> /about-us", "Services: sales, marketing, finance, logistics -> /about-us", "Exclusive U.S. customer to 350+ accounts -> /about-us", "Logistics: EDI, FDA compliance, inventory control, warehousing, Ora