any", "makes_products": "no", "type_evidence": "AES Solar has helped homeowners, businesses, schools, churches, and community organizations take control of their energy with education-first solar design and in-house installation.", "founded_year": "1999", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='aes-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='The company was established to address the procurement needs of hotels, motels, and lodging operators across the United States.

